                            Layout.fillWidth: true
                            text: themeChanger.currentPath.replace(themeChanger.basePath, "Fondos")
                            color: Qt.rgba(1, 1, 1, 0.55)
                            font.pixelSize: 10
                            elide: Text.ElideMiddle
