                                        font.pixelSize: 12
                                    }
                                }

                                MouseArea {
                                    id: upMa
                                    anchors.fill: parent
                                    hoverEnabled: true
                                    cursorShape: Qt.PointingHandCursor
                                    onClicked: navigateToDirectory(parentOf(themeChanger.currentPath))
                                }
                            }

                            delegate: Rectangle {
                                width: dirList.width
                                height: 38
                                radius: 8
                                color: dirMa.containsMouse ? Qt.rgba(1, 1, 1, 0.08) : "transparent"

