        if (isOpened) {
            folderBrowserOpen = false
            searchInput.text = ""
            wallList.currentIndex = -1

            if (themeChanger.homeDir === "") {
                homeResolver.running = true
            } else {
                currentPath = basePath
            }
            searchInput.forceActiveFocus()
        }
    }

    onCurrentPathChanged: {
        wallList.currentIndex = -1
    }

