    // "folder" está enlazado a currentPath: cada vez que currentPath cambia,
    // este modelo se recarga solo. No depende de bash, PATH ni escaping.
    FolderListModel {
        id: wallpaperFolderModel
        folder: themeChanger.currentPath !== "" ? "file://" + themeChanger.currentPath : ""
        showDirs: false
        showFiles: true
        showDotAndDotDot: false
        caseSensitive: false
        sortField: FolderListModel.Name
        nameFilters: ["*.jpg", "*.jpeg", "*.png", "*.webp", "*.bmp"]

        onStatusChanged: {
            if (status === FolderListModel.Ready) {
                console.log("[theme_panel] wallpapers encontrados:", count, "en", folder)
                // Comportamiento tipo rofi: al listar, si no hay nada seleccionado
                // todavía, resalta automáticamente el primer elemento.
                if (themeChanger.isOpened && wallList.currentIndex === -1 && count > 0) {
                    wallList.currentIndex = 0
                }
            } else if (status === FolderListModel.Error) {
                console.log("[theme_panel] ERROR al leer carpeta:", folder)
            }
        }
