        const exts = ["jpg", "jpeg", "png", "webp", "bmp"]
        const q = (query && query.length > 0) ? ("*" + query + "*") : "*"
        let filters = []
        for (let e of exts) filters.push(q + "." + e)
        wallpaperFolderModel.nameFilters = filters
        wallList.currentIndex = -1
