    // comillas/escapes de shell con rutas que tienen tildes o espacios,
    // que es la causa más probable de que el listado fallara.
Process {
    id: wallScanner
    property int revision: 0
    property string targetPath: ""
    stdout: StdioCollector {
        onStreamFinished: {
            // Ignorar si la revisión no coincide o la ruta no es la actual
            if (wallScanner.revision !== themeChanger.scanRevision) {
                console.log("[theme_panel] Resultados obsoletos ignorados (rev", wallScanner.revision, "actual", themeChanger.scanRevision, ")")
                return
            }
            let tempWallpapers = []
            const trimmed = this.text.trim()
            if (trimmed.length > 0) {
                const lines = trimmed.split('\n')
                for (let line of lines) {
                    if (!line) continue
                    let fileName = line.substring(line.lastIndexOf('/') + 1)
                    tempWallpapers.push({ path: line, name: fileName })
                }
            }
            tempWallpapers.sort((a, b) => a.name.localeCompare(b.name))
            console.log("[theme_panel] wallpapers encontrados:", tempWallpapers.length, "en", wallScanner.targetPath)
            // Solo actualizar si la ruta objetivo es la actual
            if (wallScanner.targetPath === themeChanger.currentPath) {
                themeChanger.allWallpapers = tempWallpapers
                filterWallpapers(searchInput.text)
            } else {
                console.log("[theme_panel] Ruta no coincide, ignorando resultados")
            }
        }
     }
    // ... resto i
        stderr: StdioCollector {
            onStreamFinished: {
                if (this.text.trim().length > 0) {
                    console.log("[theme_panel] wallScanner stderr:", this.text.trim())
                }
            }
        }
    }

function scanWallpapers(path) {
    if (!path) return
    console.log("[theme_panel] escaneando fondos en:", path)
    let rev = ++scanRevision   // nueva revisión
    wallScanner.running = false
    wallScanner.command = [
        "find", path,
        "-maxdepth", "1",
        "-type", "f",
        "(",
        "-iname", "*.jpg", "-o",
        "-iname", "*.jpeg", "-o",
        "-iname", "*.png", "-o",
        "-iname", "*.webp", "-o",
        "-iname", "*.bmp",
        ")"
    ]
    // Pasar la revisión como propiedad dinámica (no hay otra forma directa en QML)
    wallScanner.revision = rev
    wallScanner.targetPath = path
    wallScanner.running = true
}
    // ─── BACKEND: ESCANEO DE SUBDIRECTORIOS (para el navegador de carpetas) ───
    Process {
        id: dirScanner
        property string scannedPath: ""
        stdout: StdioCollector {
            onStreamFinished: {
                dirModel.clear()
                if (dirScanner.scannedPath !== themeChanger.basePath) {
                    let parentPath = dirScanner.scannedPath.substring(0, dirScanner.scannedPath.lastIndexOf('/'))
                    dirModel.append({ path: parentPath, name: ".. (carpeta superior)", isUp: true })
                }
                let dirs = []
                const trimmed = this.text.trim()
                if (trimmed.length > 0) {
                    const lines = trimmed.split('\n')
                    for (let line of lines) {
                        if (!line) continue
                        let dirName = line.substring(line.lastIndexOf('/') + 1)
                        dirs.push({ path: line, name: dirName })
                    }
                }
                dirs.sort((a, b) => a.name.localeCompare(b.name))
                for (let d of dirs) {
                    dirModel.append({ path: d.path, name: d.name, isUp: false })
                }
            }
        }
        stderr: StdioCollector {
            onStreamFinished: {
                if (this.text.trim().length > 0) {
                    console.log("[theme_panel] dirScanner stderr:", this.text.trim())
                }
            }
        }
    }

    function scanDirectories(path) {
        if (!path) return
        dirScanner.scannedPath = path
        dirScanner.running = false
        dirScanner.command = [
            "find", path,
            "-mindepth", "1",
            "-maxdepth", "1",
            "-type", "d",
            "-not", "-name", ".*"
        ]
        dirScanner.running = true
    }

    function navigateToDirectory(path) {
        themeChanger.currentPath = path
        scanWallpapers(path)
        scanDirectories(path)
    }

    function filterWallpapers(query) {
        filteredModel.clear()
        const q = (query || "").toLowerCase()
        for (let wp of themeChanger.allWallpapers) {
            if (wp.name.toLowerCase().includes(q)) filteredModel.append(wp)
        }
        wallList.currentIndex = -1
    }

    function applySelected() {
        let targetIdx = wallList.currentIndex >= 0 ? wallList.currentIndex : 0
        if (filteredModel.count > 0) {
            let item = filteredModel.get(targetIdx)
            themeChanger.activeWallpaperPath = item.path
            applyWallpaper(item.path)
        }
    }

    property string activeWallpaperPath: ""

    Process {
        id: themeRunner
        property string targetWallpaper: ""
        command: ["bash", "-c", "~/Personal_Scripts/pywal_global_update.sh \"" + targetWallpaper + "\""]
    }

    function applyWallpaper(path) {
        themeRunner.targetWallpaper = path
        themeRunner.running = false
        themeRunner.running = true
    }
}

